#ifdef GL_ES
precision mediump float;
#endif

// ----------------------------------------------------
// Paramètres "Shadertoy" (fournis par l’environnement)
// ----------------------------------------------------
// uniform vec2  iResolution;
// uniform float iTime;

// ----------------------------------------------------
// Paramètres physiques normalisés (G = c = 1)
// ----------------------------------------------------
const float M  = 1.0;        // Masse trou noir
const float a  = 0.8;        // Spin [0..1], 0 => Schwarzschild
const float rMax = 50.0;     // Au-delà, on considère que le rayon s'échappe
const int   MAX_STEPS = 2000;// Nombre max d’itérations d’intégration
const float H = 0.003;       // Pas d’intégration (peut ajuster)

// ----------------------------------------------------
// Horizon externe Kerr : r+ = M + sqrt(M^2 - a^2)
// ----------------------------------------------------
float horizonRadius()
{
    float inside = M*M - a*a;
    if(inside < 0.0) {
        inside = 0.0; // trou noir nu (a>M)
    }
    return M + sqrt(inside);
}

// ----------------------------------------------------
// Potentiel effectif bidouillé (façon Kerr 2D)
// ----------------------------------------------------
float Veff(float r, float L)
{
    // Terme Schwarzschild
    float blackSchw   = (L*L / (r*r))*(1.0 - 2.0*M/r);
    // Petit terme rotation => - a*L / r^3
    float rotationTerm = a*L / (r*r*r);
    return blackSchw - rotationTerm;
}

// ----------------------------------------------------
// dr/dlambda = ± sqrt(E^2 - Veff(r,L))
// ----------------------------------------------------
float radialSpeed(float r, float L, float E, bool outward)
{
    float ve = Veff(r, L);
    float sq = E*E - ve;
    if(sq < 0.0) return 0.0;
    float sign = outward ? 1.0 : -1.0;
    return sign * sqrt(sq);
}

// ----------------------------------------------------
// Intégration d'une étape (Euler simplifié)
// ----------------------------------------------------
void integrateStep(
    inout float r, inout float phi,
    inout float drdl, inout float dphidl,
    float E, float L
){
    // Signe (in/out)
    bool outward = (drdl > 0.0);
    float newDrdl = radialSpeed(r, L, E, outward);

    // MàJ drdl
    // (on fait un semi-lissage)
    drdl = mix(drdl, newDrdl, 0.5);

    // Calcul de la nouvelle position
    r += H * drdl;

    // dphi/dlambda ~ L / r^2 (on ignore frame-dragging fin)
    float newDphidl = L / (r*r);
    phi += H * 0.5*(dphidl + newDphidl);

    dphidl = newDphidl;
}

// ----------------------------------------------------
// "Sky" = fond étoilé
// ----------------------------------------------------
vec3 skyColor(vec2 fragCoord, float time)
{
    vec2 st = fragCoord * 0.03;
    st.y -= time*0.01;
    float rnd = fract(sin(dot(st, vec2(12.9898, 78.233))) * 43758.5453);
    float star = step(0.995, rnd);
    vec3 base = mix(vec3(0.0,0.0,0.2), vec3(0.0,0.0,0.3), clamp(st.y,0.0,1.0));
    return base + star*vec3(1.0);
}

// ----------------------------------------------------
// Disque d'accretion "bande" r=3..6
// ----------------------------------------------------
bool hitsAccretionDisk(float r)
{
    return (r > 3.0 && r < 6.0);
}

vec3 diskColor(float r)
{
    float t = (r - 3.0)/3.0; // [0..1]
    return mix(vec3(1.0,0.8,0.5), vec3(1.0,0.5,0.2), clamp(t,0.0,1.0));
}

// ----------------------------------------------------
// mainImage :
//   - On part de r=20M, phi=0
//   - Angle alpha = direction
//   - On intègre => trou noir, disque, ou fond
//   - ENSUITE, on impose un rayon noir sur l’écran
// ----------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalisation uv
    vec2 uv = (fragCoord / iResolution.xy)*2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // On convertit en angle
    float alpha = atan(uv.y, uv.x);

    // Setup geodesique
    float E = 1.0;
    float rCam = 20.0;
    float L = rCam * sin(alpha);

    float r = rCam;
    float phi = 0.0;
    float drdl = -cos(alpha);
    float dphidl = L/(r*r);

    // Horizon
    float rPlus = horizonRadius();

    // Flags
    bool hitBH   = false;
    bool escaped = false;
    bool hitDisk = false;

    // Intégration
    for(int i=0; i<MAX_STEPS; i++){
        // horizon ?
        if(r < rPlus){
            hitBH = true;
            break;
        }
        // échappé ?
        if(r > rMax){
            escaped = true;
            break;
        }
        // disque ?
        if(hitsAccretionDisk(r)){
            hitDisk = true;
            break;
        }
        // Avance d'un pas
        integrateStep(r, phi, drdl, dphidl, E, L);
    }

    // Couleur => selon le résultat RG
    vec3 color = vec3(0.0); // defaut : noir
    if(hitBH){
        color = vec3(0.0);      // trou noir
    }
    else if(hitDisk){
        color = diskColor(r);   // disk
    }
    else {
        color = skyColor(fragCoord, iTime); // fond
    }

    // -------------------------------------------------
    // *Imposition* d'un TROU NOIR VISUEL 
    //   => un cercle noir de rayon imposé 
    //   => par ex. 1/3 de la largeur
    // -------------------------------------------------
    float forcedRadiusScreen = iResolution.x * 0.3333 * 0.5; 
    //  => 1/3 de la largeur => le rayon = 1/6 la largeur

    // distance écran au centre
    vec2 screenCenter = 0.5 * iResolution.xy;
    float distScreen = length(fragCoord - screenCenter);

    // si dist < forcedRadiusScreen => noir total
    if(distScreen < forcedRadiusScreen){
        color = vec3(0.0);
    }

    fragColor = vec4(color, 1.0);
}
